var admin = new ServiceBusAdministrationClient(ns, new DefaultAzureCredential());

// routing decision = subscription + filter, evaluated by the broker
await admin.CreateSubscriptionAsync(
    new CreateSubscriptionOptions(topic, "PriorityRed"),
    new CreateRuleOptions("RedHigh",
        new CorrelationRuleFilter { Subject = "red", CorrelationId = "high" }));

await admin.CreateSubscriptionAsync(
    new CreateSubscriptionOptions(topic, "BlueSize10"),
    new CreateRuleOptions("Blue10", new SqlRuleFilter("color='blue' AND quantity=10")));
